  1020  deleteMembers_noInit(void *p, const UA_DataType *type) {
  1021      uintptr_t ptr = (uintptr_t)p;
  1022      u8 membersSize = type->membersSize;
  1023      for(size_t i = 0; i < membersSize; ++i) {
  1024          const UA_DataTypeMember *m= &type->members[i];
  1025          const UA_DataType *typelists[2] = { UA_TYPES, &type[-type->typeIndex] };
  1026          const UA_DataType *mt = &typelists[!m->namespaceZero][m->memberTypeIndex];
  1027          if(!m->isArray) {
  1028              ptr += m->padding;
  1029              size_t fi = mt->builtin ? mt->typeIndex : UA_BUILTIN_TYPES_COUNT;
  1030              deleteMembersJumpTable[fi]((void*)ptr, mt);
  1031              ptr += mt->memSize;
  1032          } else {
  1033              ptr += m->padding;
  1034              size_t length = *(size_t*)ptr;
  1035              ptr += sizeof(size_t);
  1036              UA_Array_delete(*(void**)ptr, length, mt);
  1037              ptr += sizeof(void*);
  1038          }
  1039      }
